function bahtText(num) {
  // amount in English words: 1234.5 → One thousand two hundred thirty-four baht and fifty satang
  const a = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
  const t = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
  const h = (n) => { let o = ''; if (n >= 100) { o += a[Math.floor(n / 100)] + ' hundred'; n %= 100; if (n) o += ' '; } if (n >= 20) { o += t[Math.floor(n / 10)] + (n % 10 ? '-' + a[n % 10] : ''); } else if (n) o += a[n]; return o; };
  const words = (n) => { if (!n) return ''; const parts = []; [[1e9, 'billion'], [1e6, 'million'], [1e3, 'thousand'], [1, '']].forEach(([v, w]) => { const q = Math.floor(n / v); if (q) { parts.push(h(q) + (w ? ' ' + w : '')); n -= q * v; } }); return parts.join(' '); };
  num = Math.round(num * 100) / 100;
  const [b, st] = num.toFixed(2).split('.');
  const bt = words(+b), sat = words(+st);
  if (!bt && !sat) return 'Zero baht';
  const s = (bt ? bt + ' baht' : '') + (sat ? (bt ? ' and ' : '') + sat + ' satang' : ' only');
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function thaiDate(iso) {
  if (!iso) return '';
  const m = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const [y, mo, da] = iso.split('-').map(Number); return da + ' ' + m[mo - 1] + ' ' + y;
}
